import java.util.Scanner;

public class Main {
    static int isLeap(int year) {
        if (year % 4 == 0 && year % 100 != 0 || year % 400 == 0)
            return 29;
        else
            return 28;
    }

    static int noOfDaysRemaining(int mon, int year) {
        int days = 0;
        switch (mon) {
            case 1: days += 31;
            case 2: days += isLeap(year);
            case 3: days += 31;
            case 4: days += 30;
            case 5: days += 31;
            case 6: days += 30;
            case 7: days += 31;
            case 8: days += 31;
            case 9: days += 30;
            case 10: days += 31;
            case 11: days += 30;
            case 12: days += 31;
        }
        return days;
    }

    static int noOfDaysPassed(int mon, int year) {
        int days = 0;
        switch (mon) {
            case 12: days += 31;
            case 11: days += 30;
            case 10: days += 31;
            case 9: days += 30;
            case 8: days += 31;
            case 7: days += 31;
            case 6: days += 30;
            case 5: days += 31;
            case 4: days += 30;
            case 3: days += 31;
            case 2: days += isLeap(year);
            case 1: days += 31;
        }
        return days;
    }

    static int noOfDays(int year) {
        return 31 * 7 + 30 * 4 + isLeap(year);
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        scanner.useDelimiter("[:\\n]");

        int yy1 = scanner.nextInt();
        int mm1 = scanner.nextInt();
        int dd1 = scanner.nextInt();
        int yy2 = scanner.nextInt();
        int mm2 = scanner.nextInt();
        int dd2 = scanner.nextInt();

        int m1, d1, y1, m2, d2, y2;

        if (yy2 > yy1) {
            m1 = mm1; y1 = yy1; d1 = dd1;
            m2 = mm2; y2 = yy2; d2 = dd2;
        } else {
            m1 = mm2; y1 = yy2; d1 = dd2;
            m2 = mm1; y2 = yy1; d2 = dd1;
        }

        int nodA = noOfDaysRemaining(m1, y1);
        int nodC = noOfDaysPassed(m2 - 1, y2);
        int nodB = 0;

        for (int i = y1 + 1; i <= y2 - 1; i++) {
            nodB += noOfDays(i);
        }

        int nod = (nodA - d1 + 1) + (nodC + d2) + nodB - 1;

        if (yy1 == yy2) {
            if (mm2 > mm1) {
                nod = (noOfDaysRemaining(mm1, yy1) - dd1 + 1) - (noOfDaysRemaining(mm2, yy2) - dd2 + 1);
            } else if (mm2 < mm1) {
                nod = (noOfDaysRemaining(mm2, yy2) - dd2 + 1) - (noOfDaysRemaining(mm1, yy1) - dd1 + 1);
            } else {
                if (dd1 > dd2)
                    nod = dd1 - dd2;
                else
                    nod = dd2 - dd1;
            }
        }

        System.out.print(nod);
    }
}

